_Static_assert(sizeof(RlpRow)==32 && sizeof(RlpBlock)==48,"actor ABI");
_Static_assert(sizeof(RleCritic)==16 && sizeof(RleWorld)==24 && sizeof(RleRow)==120,"rollout ABI");
_Static_assert(sizeof(RleBatch)==61872 && offsetof(RleBatch,rows)==48 && offsetof(RleBatch,next_worlds)==61488,"batch ABI");
_Static_assert(sizeof(RltOptimizer)==40 && sizeof(RltEpoch)==96 && sizeof(RltState)==440,"update ABI");
_Static_assert(sizeof(RltIteration)==62696 && offsetof(RltIteration,epochs)==61872 && offsetof(RltIteration,next)==62256,"iteration ABI");
_Static_assert(sizeof(RlsEvaluation)==64 && sizeof(RlsQuality)==200 && sizeof(RlpCoefficient)==88,"diagnostic ABI");
static uint64_t assertions,refusals,aliases,fixture_rollout_steps,fixture_eval_steps,fixture_transitions,fixture_epochs,fixture_blocks;
#define NEED(c) do { ++assertions; if(!(c)){fprintf(stderr,"LQR native failure %s:%d: %s\n",__FILE__,__LINE__,#c);exit(2);} }while(0)
static void wr(FILE*f,const void*p,size_t n){NEED(fwrite(p,1,n,f)==n);}
static void rd(FILE*f,void*p,size_t n){NEED(fread(p,1,n,f)==n);}
static void finish(FILE*f){NEED(fflush(f)==0);NEED(fsync(fileno(f))==0);NEED(fclose(f)==0);}
static FILE* opened(const char*dir,const char*name,const char*mode){char p[4096];NEED(snprintf(p,sizeof p,"%s/%s",dir,name)>0);FILE*f=fopen(p,mode);NEED(f!=NULL);return f;}
static void* load(const char*dir,const char*name,size_t width,size_t*count){FILE*f=opened(dir,name,"rb");NEED(fseek(f,0,SEEK_END)==0);long n=ftell(f);NEED(n>=0 && (size_t)n%width==0);NEED(fseek(f,0,SEEK_SET)==0);void*p=calloc(1,(size_t)n+1);NEED(p);rd(f,p,(size_t)n);NEED(fclose(f)==0);*count=(size_t)n/width;return p;}
static void qi(FILE*f,int64_t x){wr(f,&x,8);}static void du(FILE*f,uint64_t x){wr(f,&x,8);}static void df(FILE*f,double x){NEED(isfinite(x));wr(f,&x,8);}
static void optimizer(FILE*f,const RltOptimizer*x){df(f,x->K);df(f,x->m);df(f,x->v);qi(f,x->adam.step);qi(f,x->adam.skipped);}
static void world(FILE*f,const RleWorld*x){df(f,x->x);du(f,x->rng.seed);du(f,x->rng.counter);}
static void row(FILE*f,const RleRow*x){df(f,x->x);df(f,x->action);df(f,x->next_x);df(f,x->old_logp);df(f,x->z);df(f,x->step.reward.value);df(f,x->step.current_value.value);df(f,x->step.next_value.value);qi(f,x->step.terminated);qi(f,x->step.truncated);df(f,x->target.delta.value);df(f,x->target.advantage.value);df(f,x->target.lambda_return.value);qi(f,x->target.bootstrap);qi(f,x->target.trace);}
static void batch(FILE*f,const RleBatch*x){qi(f,x->worlds);qi(f,x->horizon);qi(f,x->count);df(f,x->K_old);df(f,x->P);df(f,x->C);for(int i=0;i<512;i++)row(f,&x->rows.e[i]);for(int i=0;i<16;i++)world(f,&x->next_worlds.e[i]);}
static void epoch(FILE*f,const RltEpoch*x){optimizer(f,&x->next);df(f,x->actual_loss_mean);df(f,x->gradient_mean);df(f,x->unprojectedK);qi(f,x->projection);qi(f,x->rows);qi(f,x->blocks);qi(f,x->clipped);}
static void state(FILE*f,const RltState*x){optimizer(f,&x->optimizer);for(int i=0;i<16;i++)world(f,&x->worlds.e[i]);qi(f,x->batch);du(f,x->runseed);}
static void read_state(FILE*f,RltState*x){memset(x,0,sizeof*x);rd(f,&x->optimizer.K,8);rd(f,&x->optimizer.m,8);rd(f,&x->optimizer.v,8);rd(f,&x->optimizer.adam.step,8);rd(f,&x->optimizer.adam.skipped,8);for(int i=0;i<16;i++){rd(f,&x->worlds.e[i].x,8);rd(f,&x->worlds.e[i].rng.seed,8);rd(f,&x->worlds.e[i].rng.counter,8);}rd(f,&x->batch,8);rd(f,&x->runseed,8);}
static void iteration(FILE*f,const RltIteration*x){batch(f,&x->batch);for(int i=0;i<4;i++)epoch(f,&x->epochs.e[i]);state(f,&x->next);}
static void evaluation(FILE*f,const RlsEvaluation*x){df(f,x->K);df(f,x->finite_cost);df(f,x->tail);df(f,x->result);df(f,x->analytic);df(f,x->final_x);df(f,x->discount);qi(f,x->steps);}
static void quality(FILE*f,const RlsQuality*x){df(f,x->K);df(f,x->Pstar);df(f,x->Kstar);df(f,x->gain_error);df(f,x->max_relative_gap);for(int i=0;i<6;i++)df(f,x->relative_gap.e[i]);for(int i=0;i<6;i++)df(f,x->nominal_cost.e[i]);for(int i=0;i<6;i++)df(f,x->optimal_cost.e[i]);qi(f,x->gain_ok);qi(f,x->gap_ok);}
static void coefficient(FILE*f,const RlpCoefficient*x){df(f,x->density.logp);df(f,x->density.score_mean);df(f,x->density.score_logstd);df(f,x->density.entropy);df(f,x->ratio.log_ratio);df(f,x->ratio.ratio);df(f,x->ratio.objective.surrogate.value);df(f,x->ratio.objective.loss.value);df(f,x->ratio.objective.dloss_dlogp.value);df(f,x->ratio.objective.clipped_ratio);qi(f,x->ratio.objective.clipped_active);}
// Calls are staged through a full physical guard, including spare output storage.
enum{BLOCK,CRITIC,TRANSITION,PROJECT,EPOCH,EVALUATE,SCORE,ROLLOUT,BEGIN,BATCH,COEFFICIENT,INVERSE};
static const size_t widths[]={48,16,120,8,96,64,200,61872,440,62696,88,8};
typedef struct {double K,Kold,x,action,z,candidate;int64_t n,outn,W,H,start,steps;uint64_t seed;RlpRow*rows;RleWorld*worlds;RltOptimizer opt;RltState state;} Args;
static int call(int k,Args*a,void*out){switch(k){case BLOCK:return rlp_block(a->K,(coax_v_t_RlpRow){a->rows,a->n},(coax_v_t_RlpBlock){out,a->outn});case CRITIC:return rle_critic(a->K,(coax_v_t_RleCritic){out,a->outn});case TRANSITION:return rle_transition(a->K,a->x,a->action,a->z,(coax_v_t_RleRow){out,a->outn});case PROJECT:return rlt_project(a->Kold,a->candidate,(coax_v_f64){out,a->outn});case EPOCH:return rlt_epoch(a->Kold,a->opt,(coax_v_t_RlpRow){a->rows,a->n},(coax_v_t_RltEpoch){out,a->outn});case EVALUATE:return rls_evaluate(a->K,a->start,a->steps,(coax_v_t_RlsEvaluation){out,a->outn});case SCORE:return rls_score(a->K,(coax_v_t_RlsQuality){out,a->outn});case ROLLOUT:return rle_rollout(a->W,a->H,a->K,(coax_v_t_RleWorld){a->worlds,a->n},(coax_v_t_RleBatch){out,a->outn});case BEGIN:return rlt_begin(a->seed,(coax_v_t_RltState){out,a->outn});case BATCH:return rlt_batch(a->state,(coax_v_t_RltIteration){out,a->outn});case COEFFICIENT:return rlp_coefficients(a->K,a->rows[0],(coax_v_t_RlpCoefficient){out,a->outn});default:return rlp_inverse_sigma((coax_v_f64){out,a->outn});}}
static int checked(int k,Args*a,void*out,int want){size_t w=widths[k],total=64+2*w;unsigned char*p=malloc(total),*old=malloc(total);NEED(p&&old);memset(p,0xa5,total);memcpy(old,p,total);void*r=p+32;size_t inbytes=(k==BLOCK||k==EPOCH)?(a->n>0&&a->n<=512?(size_t)a->n*32:0):(k==ROLLOUT?(a->n>0&&a->n<=16?(size_t)a->n*24:0):0);void*inp=k==ROLLOUT?(void*)a->worlds:(void*)a->rows;void*snap=malloc(inbytes+1);NEED(snap);if(inbytes)memcpy(snap,inp,inbytes);Args prior=*a;int s=call(k,a,r);NEED(s==want);NEED(!memcmp(a,&prior,sizeof prior));if(inbytes)NEED(!memcmp(snap,inp,inbytes));NEED(!memcmp(p,old,32));NEED(!memcmp(p+32+w,old+32+w,total-32-w));if(s){NEED(!memcmp(p,old,total));++refusals;}else{if(out)memcpy(out,r,w);if(k==ROLLOUT)fixture_rollout_steps+=(uint64_t)((RleBatch*)r)->count;if(k==EVALUATE)fixture_eval_steps+=(uint64_t)((RlsEvaluation*)r)->steps;if(k==TRANSITION)++fixture_transitions;if(k==EPOCH){++fixture_epochs;fixture_blocks+=(uint64_t)((RltEpoch*)r)->blocks;}if(k==BLOCK)++fixture_blocks;}free(snap);free(old);free(p);return s;}
static Args base(RlpRow*r,RleWorld*w){Args a;memset(&a,0,sizeof a);a.K=.5;a.Kold=.5;a.x=1;a.action=-.5;a.z=0;a.candidate=.6;a.n=1;a.outn=1;a.W=1;a.H=1;a.start=0;a.steps=1;a.rows=r;a.worlds=w;a.opt.K=.5;return a;}
static void overlap(int k,Args a,size_t source_offset,size_t output_offset){size_t w=widths[k],n=(size_t)a.n*(k==ROLLOUT?24:32),total=128+w+n;unsigned char*p=malloc(total),*before=malloc(total),*expected=malloc(w);NEED(p&&before&&expected);memset(p,0x3c,total);void*input=k==ROLLOUT?(void*)a.worlds:(void*)a.rows;memcpy(p+32+source_offset,input,n);Args b=a;if(k==ROLLOUT)b.worlds=(RleWorld*)(p+32+source_offset);else b.rows=(RlpRow*)(p+32+source_offset);checked(k,&a,expected,0);memcpy(before,p,total);int s=call(k,&b,p+32+output_offset);NEED(s==0);NEED(!memcmp(p+32+output_offset,expected,w));NEED(!memcmp(p,before,32+output_offset));NEED(!memcmp(p+32+output_offset+w,before+32+output_offset+w,total-32-output_offset-w));if(k==ROLLOUT)fixture_rollout_steps+=(uint64_t)((RleBatch*)expected)->count;if(k==EPOCH){++fixture_epochs;fixture_blocks+=(uint64_t)((RltEpoch*)expected)->blocks;}if(k==BLOCK)++fixture_blocks;++aliases;free(expected);free(before);free(p);}
static void overlap_refusal(int k,Args a,int want){size_t w=widths[k],n=(size_t)a.n*(k==ROLLOUT?24:32),total=128+w+n;unsigned char*p=malloc(total),*before=malloc(total);NEED(p&&before);memset(p,0x3c,total);void*input=k==ROLLOUT?(void*)a.worlds:(void*)a.rows;memcpy(p+32,input,n);if(k==ROLLOUT)a.worlds=(RleWorld*)(p+32);else a.rows=(RlpRow*)(p+32);memcpy(before,p,total);NEED(call(k,&a,p+32)==want);NEED(!memcmp(p,before,total));++refusals;++aliases;free(before);free(p);}
