static void packet(FILE*f,int k,const void*x){qi(f,0);switch(k){case BLOCK:{const RlpBlock*a=x;df(f,a->actual_loss_sum);df(f,a->gradient_sum);df(f,a->vjp_proxy);qi(f,a->rows);qi(f,a->nodes);qi(f,a->clipped);break;}case CRITIC:{const RleCritic*a=x;df(f,a->P);df(f,a->C);break;}case TRANSITION:row(f,x);break;case PROJECT:df(f,*(double*)x);break;case EPOCH:epoch(f,x);break;case EVALUATE:evaluation(f,x);break;case SCORE:quality(f,x);break;case ROLLOUT:batch(f,x);break;default:state(f,x);}}
